#include <stdio.h>
#define GOLD 0
int main(void) {
    int n, evenSum = 0, negatives = 0;
    if (scanf("%d", &n) != 1) return 1;
#if GOLD
    int run = 0, longest = 0;
#endif
    for (int i = 0; i < n; i++) {
        int value;
        if (scanf("%d", &value) != 1) return 1;
        if (value > 0 && value % 2 == 0) evenSum += value;
        if (value < 0) negatives++;
#if GOLD
        run = value > 0 ? run + 1 : 0;
        if (run > longest) longest = run;
#endif
    }
    printf("even_sum=%d negatives=%d", evenSum, negatives);
#if GOLD
    printf(" longest=%d", longest);
#endif
    printf("\n");
    return 0;
}

