#include <stdio.h>
#define GOLD 0
int main(void) {
    int n, readings[20], sum = 0;
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &readings[i]) != 1) return 1;
        sum += readings[i];
    }
    int low = readings[0], high = readings[0], first = 0;
    for (int i = 1; i < n; i++) {
        if (readings[i] < low) low = readings[i];
        if (readings[i] > high) { high = readings[i]; first = i; }
    }
    printf("min=%d max=%d first_max=%d", low, high, first);
#if GOLD
    int above = 0, average = sum / n;
    for (int i = 0; i < n; i++) if (readings[i] > average) above++;
    printf(" above_avg=%d", above);
#endif
    printf("\n");
    return 0;
}

